Dada la función siguiente, ¿qué llamada es válida?
func greet(name: String) -> String {
    "Hi, \(name)"
}

¿Qué imprime este código?
func double(_ x: Int) -> Int { x * 2 }
print(double(3) + 1)

¿Qué imprime este código?
func hello(name: String = "World") {
    print("Hello, \(name)")
}
hello()

